"""Randomised request generator producing legal (and sometimes illegal) sessions."""
import json, random, sys
sys.path.insert(0, '/workspace/dev')
from ref import Topo

TOPOS = [
    ['leaf-spine', 3, 1], ['leaf-spine', 4, 2], ['leaf-spine', 6, 2], ['leaf-spine', 2, 1],
    ['leaf-spine', 5, 0 + 2],
    ['clos', 4, 'tor', 0], ['clos', 4, 'pod', 1], ['clos', 6, 'tor', 1], ['clos', 6, 'pod', 0],
    ['clos', 8, 'tor', 1], ['clos', 8, 'pod', 1], ['clos', 4, 'tor', 1],
    ['torus2d', 3, 'host'], ['torus2d', 4, 'row'], ['torus2d', 5, 'host'], ['torus2d', 4, 'host'],
    ['torus2d', 6, 'host'], ['torus2d', 3, 'row'],
    ['torus3d', 3, 'host'], ['torus3d', 4, 'line'], ['torus3d', 3, 'line'],
    ['dragonfly', 4, 3, 1, 'router'], ['dragonfly', 4, 3, 1, 'group'], ['dragonfly', 4, 3, 1, 'target'],
    ['dragonfly', 3, 2, 1, 'group'], ['dragonfly', 6, 5, 1, 'target'], ['dragonfly', 9, 4, 2, 'group'],
    ['dragonfly-plus', 4, 2, 3, 1, 0, 'tor'], ['dragonfly-plus', 4, 2, 3, 1, 0, 'group'],
    ['dragonfly-plus', 3, 4, 2, 0, 1, 'group'], ['dragonfly-plus', 2, 2, 1, 1, 0, 'tor'],
    ['dragonfly-plus', 5, 3, 2, 1, 0, 'group'], ['dragonfly-plus', 3, 2, 1, 0, 1, 'tor'],
]

def build_session(rng, spec, ntasks=None, ngroups=None, ntx=None, edit_count=None,
                  wild=0.5, pins=True, force_bad=None, empty_tasks=False):
    topo = Topo(spec)
    n = topo.n
    tcount = len(topo.foots)
    by_dom = {}
    for tid, dom in enumerate(topo.domains):
        by_dom.setdefault(dom, []).append(tid)
    doms = sorted(by_dom)
    g = ngroups if ngroups is not None else rng.randint(1, min(10, max(1, tcount)))
    g = max(g, 1)
    keys = []
    nkeys = max(1, min(len(doms), rng.randint(1, 4)))
    for _ in range(nkeys):
        keys.append((rng.choice(doms), rng.choice([0, 1, 7, 42])))
    groups = []
    gkey = []
    for gid in range(g):
        dom, cls = rng.choice(keys)
        quota = rng.randint(1, 8)
        budget = rng.choice([1, 3, 100, 10 ** 12])
        groups.append([quota, budget])
        gkey.append((dom, cls))
    same_key = [[h for h in range(g) if gkey[h] == gkey[gid]] for gid in range(g)]
    d = 0 if empty_tasks else (ntasks if ntasks is not None else rng.randint(1, 40))
    tasks = []
    for tid in range(d):
        gid = rng.randrange(g)
        dom, cls = gkey[gid]
        tpl = rng.choice(by_dom[dom])
        weight = rng.randint(1, max(1, min(4, groups[gid][0] * groups[gid][1])))
        pin = 1 if (pins and rng.random() < 0.3) else 0
        tasks.append([tpl, gid, weight, cls, pin])
    fp = [set() for _ in range(g)]
    for t in tasks:
        fp[t[1]] |= set(topo.foots[t[0]])
    caps = [0] * n
    for gid in range(g):
        if not fp[gid]:
            continue
        for x in fp[gid]:
            caps[x] += groups[gid][0]
    for x in range(n):
        if rng.random() < 0.45:
            caps[x] += rng.randint(0, 6)
    loads = [sum(t[2] for t in tasks if t[1] == gid) for gid in range(g)]

    if force_bad == 'mixed' and d >= 2:
        tasks[1][3] = tasks[0][3] + 5
    elif force_bad == 'quota0' and d >= 1:
        groups[tasks[0][1]][0] = 0
    elif force_bad == 'work' and d >= 1:
        idx = max(range(d), key=lambda i: tasks[i][2])
        groups[tasks[idx][1]] = [1, 1]
        tasks[idx][2] = 10 ** 9
    elif force_bad == 'capacity' and d >= 1:
        gid = tasks[0][1]
        if fp[gid]:
            caps[min(fp[gid])] = 0
        else:
            return None
    elif force_bad == 'range':
        if d == 0:
            return None
        tasks[0][0] = tcount
    elif force_bad == 'emptyquotaok' and d >= 1:
        pass

    def qmake():
        return {'groups': [rng.randrange(g) for _ in range(rng.randint(0, 5))],
                'nodes': [rng.randrange(n) for _ in range(rng.randint(0, 6))],
                'tasks': [rng.randrange(d) for _ in range(rng.randint(0, 5))] if d else []}

    txs = []
    for _ in range(ntx if ntx is not None else rng.randint(0, 12)):
        stale = rng.random() < 0.1
        r = rng.choice([0, 1, 2, 10 ** 9]) if stale else None
        # revision tracking is approximate; the reference/candidate decides
        edits = []
        count = edit_count if edit_count is not None else rng.randint(0, 8)
        chaotic = rng.random() < wild
        for _ in range(count):
            kinds = ['move', 'weight', 'class', 'bind', 'pin', 'quota', 'budget', 'cap']
            weights = [10, 10, 6, 6, 6, 8, 6, 8] if chaotic else [12, 8, 2, 4, 6, 6, 4, 6]
            kind = rng.choices(kinds, weights=weights)[0]
            if kind in ('move', 'weight', 'class', 'bind', 'pin'):
                if d == 0:
                    kind = 'quota' if g else 'cap'
                else:
                    tid = rng.randrange(d)
                    if kind == 'move':
                        pool = same_key[tid and tasks[tid][1]] if not chaotic else list(range(g))
                        if chaotic and rng.random() < .5:
                            pool = list(range(g))
                        edits.append(['move', tid, rng.choice(pool)])
                    elif kind == 'weight':
                        hi = 10 ** 9 if chaotic else 6
                        edits.append(['weight', tid, rng.randint(1, hi)])
                    elif kind == 'class':
                        edits.append(['class', tid, rng.choice([0, 1, 7, 42, 10 ** 9] if chaotic else [gkey[tasks[tid][1]][1]])])
                    elif kind == 'bind':
                        if chaotic:
                            edits.append(['bind', tid, rng.randrange(tcount)])
                        else:
                            edits.append(['bind', tid, rng.choice(by_dom[gkey[tasks[tid][1]][0]])])
                    elif kind == 'pin':
                        edits.append(['pin', tid, rng.randint(0, 1)])
                    continue
            if kind == 'quota':
                if g == 0:
                    continue
                edits.append(['quota', rng.randrange(g), rng.randint(0, 64) if chaotic else rng.randint(1, 20)])
            elif kind == 'budget':
                if g == 0:
                    continue
                edits.append(['budget', rng.randrange(g), rng.choice([1, 10 ** 12]) if chaotic else rng.choice([10, 10 ** 12])])
            elif kind == 'cap':
                edits.append(['cap', rng.randrange(n), rng.randint(0, 10 ** 9) if chaotic else rng.randint(4, 60)])
        txs.append({'revision': r, 'edits': edits, 'query': qmake()})
    if r is None:
        pass
    # first pass revision values default: set sequentially below in driver
    return {'topology': spec, 'caps': caps, 'groups': groups, 'tasks': tasks,
            'query': qmake(), 'transactions': txs, '_loads': loads}

def sequential_revisions(rng, session, share=0.85):
    """Rewrite transaction revisions so most of them match the running counter."""
    rev = 0
    for tx in session['transactions']:
        if tx['revision'] is None:
            tx['revision'] = rev
        # transactions may be accepted or rejected; keep mostly the live counter
    # simulate accept/reject quickly is impossible here; leave as-is
    return session

def build_request(seed, sessions=2, force_bad=None, **kw):
    rng = random.Random(seed)
    out = []
    for _ in range(sessions):
        spec = rng.choice(TOPOS)
        s = build_session(rng, spec, force_bad=force_bad, **kw)
        if s is None:
            continue
        s.pop('_loads', None)
        # transaction revisions: chain them so that accepted ones advance
        rev = 0
        for tx in s['transactions']:
            if tx['revision'] is None:
                tx['revision'] = rev
                rev += 1
            else:
                tx['revision'] = 0
        out.append(s)
    return {'version': 2, 'sessions': out}

if __name__ == '__main__':
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
    print(json.dumps(build_request(seed), separators=(',', ':')))
